<?php

declare(strict_types=1);

namespace Dakotajune\Seeders\Support;

use Illuminate\Filesystem\Filesystem;
use InvalidArgumentException;

/**
 * Writes generated files, and decides what to do with one that is already there.
 *
 * Every file starts with a header carrying a hash of what follows it (taken over `\n` line endings, so Windows, git's
 * autocrlf and an editor's idea of a line ending do not look like edits). That lets a later build tell a file it wrote
 * and nobody touched from one somebody edited.
 *
 *   always   (default, as Blueprint does)  overwrite whatever is there
 *   protect  overwrite only what this package wrote and nobody edited; skip the rest and say why
 *   never    only create files that are not there
 */
final class FileGuard
{
    private const HEADER = '// @generated by dakotajune/seeders [hash:%s]';

    public function __construct(
        private readonly Filesystem $files,
        private readonly string $policy = 'always',
        private readonly bool $dryRun = false,
    ) {
        if (! in_array($policy, ['always', 'protect', 'never'], true)) {
            throw new InvalidArgumentException("seeders.overwrite must be always, protect or never, not \"{$policy}\".");
        }
    }

    /** The source with the header line added after `<?php`. */
    public static function stamp(string $source): string
    {
        $source = Eol::lf($source);

        return (string) preg_replace('/^<\?php\n/', "<?php\n" . sprintf(self::HEADER, Eol::hash($source)) . "\n", $source, 1);
    }

    /**
     * @return array{0: ?string, 1: string} the hash the header recorded (null when there is no header) and the source without it
     */
    public static function unstamp(string $source): array
    {
        $source = Eol::lf($source);

        if (preg_match('/^<\?php\n\/\/ @generated by dakotajune\/seeders \[hash:([0-9a-f]{40})\]\n/', $source, $m) !== 1) {
            return [null, $source];
        }

        return [$m[1], '<?php' . "\n" . substr($source, strlen($m[0]))];
    }

    /**
     * @param  bool  $guardHandWritten  leave a file that is not ours alone even under `always`, unless it is Laravel's own stub (for DatabaseSeeder)
     */
    public function write(string $path, string $source, bool $guardHandWritten = false): Decision
    {
        $stamped = self::stamp($source);

        if (! $this->files->exists($path)) {
            return $this->apply(new Decision('created', $path, null, null, $stamped), $stamped);
        }

        $existing = Eol::lf((string) $this->files->get($path));

        if ($existing === $stamped) {
            return new Decision('unchanged', $path, null, $existing, $stamped);
        }

        [$recorded, $bare] = self::unstamp($existing);
        $ours = $recorded !== null;
        $edited = $ours && Eol::hash($bare) !== $recorded;

        $skip = fn (string $reason): Decision => new Decision('skipped', $path, $reason, $existing, $stamped);

        if ($guardHandWritten && ! $ours && ! StockDatabaseSeeder::matches($existing)) {
            return $skip('hand-written, so it is left alone');
        }

        $decision = match ($this->policy) {
            'never' => $skip('it already exists (seeders.overwrite is never)'),
            'protect' => match (true) {
                ! $ours => $skip('it was not generated by this package (seeders.overwrite is protect)'),
                $edited => $skip('it was edited by hand since it was generated (seeders.overwrite is protect)'),
                default => new Decision('updated', $path, null, $existing, $stamped),
            },
            default => new Decision('updated', $path, null, $existing, $stamped),
        };

        return $decision->action === 'skipped' ? $decision : $this->apply($decision, $stamped);
    }

    private function apply(Decision $decision, string $stamped): Decision
    {
        if (! $this->dryRun) {
            if (! $this->files->exists(dirname($decision->path))) {
                $this->files->makeDirectory(dirname($decision->path), 0755, true);
            }

            $this->files->put($decision->path, Eol::to($stamped));
        }

        return $decision;
    }
}
